use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_and_preserves_error_behavior() {
    let config = RetryConfig::new(4, 5, 12);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 | 2 => Err(RetryError::Transient("temporary".to_owned())),
            _ => Err(RetryError::Permanent("invalid job".to_owned())),
        }
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".to_owned())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![5, 10]);
}

